import { useState } from "react";

export function KeyboardShortcutOverlay({
  title = "{{title}}",
  hint = "{{hint}}",
  columns = "{{columns}}",
  accent = "{{accent}}",
  open: initialOpen = {{open}},
}) {
  const [open, setOpen] = useState(initialOpen);
  const shortcuts = [
    ["Command palette", "Ctrl+K"],
    ["Search", "/"],
    ["New item", "N"],
    ["Save", "Ctrl+S"],
    ["Toggle sidebar", "["],
    ["This panel", "?"],
  ];
  return (
    <div style={{ position: "relative", minHeight: 220, fontFamily: "system-ui, sans-serif", background: "#FAF7F2", borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <button type="button" onClick={() => setOpen(true)} style={{ background: "#fff", border: "1.5px solid #24143030", borderRadius: 8, padding: "9px 14px", fontSize: 13.5, color: "#241430", cursor: "pointer" }}>
        Press <kbd style={{ background: accent, borderRadius: 4, padding: "1px 6px" }}>?</kbd> for shortcuts
      </button>
      {open && (
        <div style={{ position: "absolute", inset: 0, background: "#24143066", borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div role="dialog" aria-label={title} style={{ width: 300, maxWidth: "88%", background: "#FAF7F2", borderRadius: 12, padding: 18, boxShadow: "0 20px 40px rgba(36,20,48,.3)" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
              <h3 style={{ margin: 0, fontSize: 16, fontWeight: 600, color: "#241430" }}>{title}</h3>
              <button type="button" aria-label="Close shortcuts" onClick={() => setOpen(false)} style={{ background: "transparent", border: "none", fontSize: 16, lineHeight: 1, cursor: "pointer", color: "#241430" }}>&times;</button>
            </div>
            <dl style={{ margin: 0, display: "grid", gridTemplateColumns: columns === "two" ? "1fr 1fr" : "1fr", gap: "8px 16px" }}>
              {shortcuts.map(([name, key]) => (
                <div key={name} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
                  <dt style={{ margin: 0, fontSize: 12.5, color: "#241430cc" }}>{name}</dt>
                  <dd style={{ margin: 0 }}><kbd style={{ background: accent, borderRadius: 4, padding: "1px 6px", fontSize: 11.5 }}>{key}</kbd></dd>
                </div>
              ))}
            </dl>
            <p style={{ margin: "14px 0 0", fontSize: 11.5, color: "#24143099", textAlign: "center" }}>{hint}</p>
          </div>
        </div>
      )}
    </div>
  );
}
